#include "config.h"
#include <concord/discord_codecs.h>

void on_message(struct discord *client, const struct discord_message *event)
{
  if (!event || !event->author) return;
  if (event->author->bot) return;

  // Print out what the content actually is to debug
  if (event->content)
  {
    printf("Message content was: '%s'\n", event->content);
    
    if (strstr(event->content, "unix") != NULL || strstr(event->content, "UNIX") != NULL)
    {
      printf("Message contained %s\n", event->content);
      struct discord_create_message params1 = { .content = "It started in the 1960s. AT&T created the corporation Bell Labs. Bell Labs was created because Alexander Graham Bell (the creator of the telephone) created the company later known as AT&T. So AT&T was the only phone carrier until the patent they owned expired in the 1940s. So to guarantee stability in the new market, they made a deal with the US government to create Bell Labs. Fast forward 20 years. At Bell Labs, they were working on an operating system called Multics. But the code was more bloated than me after visiting the dining center and was later abandoned. Two guys named Ken Thompson and Dennis Ritchie teamed up and Thompson wrote a code for a very minimal OS in a week. He called it Unics. Later renamed to UNIX. It built from there and eventually became the main OS for AT&T. Over the years, Ritchie was working on making his own programming language called C. Eventually in 1973, he recreated UNIX in C as the Assembly language was hard to deal with. From there it grew and grew. But there was an issue: because AT&T created Bell Labs as part of a government sanctioned collab, under their leadership, Thompson and Ritchie couldn't sell UNIX. But they found a loophole by giving away the code to universities. By 1974, Thompson went to teach at UCB (University of California Berkely). He brought the code for UNIX with him. In 1977, he created a fork of UNIX called Berkely Software Distribution (or BSD). By 1984, the AT&T deal with the government broke up. AT&T then realized UNIX would be a multi-billion dollar asset. They hid the source code, and created extreme licensing deals for companies. When they sold UNIX licenses to companies, it was a different version. UNIX the licensed to IBM was different from the one they licensed to HP. They did this to be a monopolistic dick. Enter Richard Stallman." };
      struct discord_create_message params2 = { .content = "Stallman worked at a company in the 70s. He had an issue with the printer they had there. He wanted to create a system where if the machine jammed (which was very often), he would get an alert. But to do that, he needed the driver source code. He asked the company, and they said no. So he quit his job and founded the GNU project on the grounds all software should be free and open source. Whether or not you agree, it was very important to this story. GNU is a recurring acronym. It stands for GNU is Not UNIX. He also created the Free Software Foundation or FSF. He founded a team to create an operating system just like UNIX. By 1990, he and his team created all the commands and functions from scratch that UNIX used, but they were missing the OS kernel. Enter Linus Torvalds. Linus was a then 21 year old computer science major at the University of Helsinki. Stallman was doing a lecture at the University of Helsinki and a friend of Torvalds convinced him to go to it. Seeing Stallman had an impact on Torvalds. He described him as looking like \"a hacker\" with his long hair and beard." };
      struct discord_create_message params3 = { .content = "The way Stallman viewed things made Torvalds think. Torvalds had already begun working on his own UNIX inspired kernel as he wanted a UNIX computer but couldn't afford the $5,000 tag. At the time he called his version Freax. He continued working on his kernel and posted the code online where someone recommended he change the name to Linux. Combining his name Linus and UNIX. Using the tools Stallman and his team made, Torvalds integrated the UNIX tools that GNU had made into Linux and it was born. During that time, the people at Berkely wanted to make BSD open source by removing all of AT&T's code from the BSD code. But once again, AT&T was being a dick. Lawsuit! It was dragging on for two years. During that time, developers moved to Linux because they didn't want to deal with AT&T. This was 1992. In 1993, a group of developers took BSD's source code and created a more optimized version of it called FreeBSD. FreeBSD and Linux are very similar in that it's like my web server. My web server is inspired by NGINX, but uses zero code from it." };
      struct discord_create_message params4 = { .content = "That's just like Linux: built from scratch inspired by UNIX. FreeBSD took the foundation from UNIX, and built their building on top of the preexisting work. When the lawsuit ended, Berkely agreed to remove the final parts of code that were AT&T's and rewrote them from scratch. They then released a new version of BSD called 4.4-Lite. FreeBSD then was reworked to be based off this new version of BSD. Later in 1996 another version based on BSD came out called OpenBSD. What's the difference between FreeBSD and OpenBSD? They're like siblings. Same build code, different features. FreeBSD is more for performance while OpenBSD is more focused on security. Similar to TCP/UDP how TCP is more so focused on stability and UDP speed. What's weird is the same people who made OpenBSD made OpenSSH and not OpenSSL. It's confusing, and I barley understand it. Here's another fun fact: MacOS is UNIX. When Steve Jobs was kicked out of Apple in 1985, he founded another company called NeXT. He created an OS based off the BSD code called NeXTSTEP. NeXT was later acquired by Apple again in the late 90s. Steve Jobs then became CEO of Apple. That whole story is something else I should look into. But anyway, by 2001, the aging OS made for the Macintosh computers was unreliable. So they took NeXTSTEP and updated its code with elements of FreeBSD and rebranded it as MacOS. What's crazy is that MacOS is official UNIX. And that's how the UNIX family lived on. AT&T's UNIX is still in use today, but really only for major corporations like banks." };
      
      if (discord_create_message(client, event->channel_id, &params1, NULL) != 0) printf("ERROR. Message failed to create\n");
      if (discord_create_message(client, event->channel_id, &params2, NULL) != 0) printf("ERROR. param2 failed to create\n");
      if (discord_create_message(client, event->channel_id, &params3, NULL) != 0) printf("ERROR. param3 failed to create\n");
      if (discord_create_message(client, event->channel_id, &params4, NULL) != 0) printf("ERROR. param4 failed to create\n");
    }
  }
  else 
  {
    printf("event->content is NULL!\n");
  }
}